// ═══════════════════════════════════════════════════════════════════════════
// audio_vars.js — n8n Code-узел «Vars» конвейера озвучки шота (n8n на .99). Mode: Run Once for All Items.
//
// Озвучка шота = текст шота (dialogue_text: рассказчик или реплика) голосом говорящего через tts-proxy
// (n8n на 88.99 ходит в Google Gemini TTS и отдаёт wav). Файл ляжет рядом с кадрами серии.
//
// Голос: scenes.speaking_character_voice (ручная замена на шоте) → characters.voice_name говорящего.
// Подача (style), коротко: описание голоса персонажа (characters.voice_profile, 2–5 слов) + «Say in a <тон> tone»
// (тон — dialogue_direction шота / speaker_voice_tone). Длинная режиссура хуже: модель читает её вслух или обрывается.
// Выход: scene_id, text, voice, style, tts_url, local_comfy_url, output_dir, file_name
// Узлы: SCENE_NODE, TOPIC_NODE, SEASON_NODE, CHARACTERS_NODE (Supabase).
// ═══════════════════════════════════════════════════════════════════════════

const SCENE_NODE = 'Scene'
const TOPIC_NODE = 'Topic'
const SEASON_NODE = 'Season'
const CHARACTERS_NODE = 'Characters'

// ── Настройки ──────────────────────────────────────────────────────────────
const TTS_URL = 'http://127.0.0.1:8190/webhook/3cce057a-d32b-45bf-80fc-616f7aaa3bba' // tts-proxy на 88.99 через туннель thai-tunnel (.99 → Таиланд → 88.99): напрямую из России ответ замирает на ~30 КБ
const LOCAL_COMFY_URL = 'http://127.0.0.1:8188' // свой ComfyUI: /upload/image?type=output кладёт wav в output .99
const NARRATOR = 'NARRATOR'
const NARRATOR_VOICE = 'Warm, calm documentary storyteller' // если у персонажа Narrator не заполнен voice_profile
// ───────────────────────────────────────────────────────────────────────────

const norm = (v) => String(v ?? '').toUpperCase().replace(/[^A-Z0-9]/g, '')
const clean = (s) => String(s ?? '').replace(/\s+/g, ' ').trim()
const profileText = (p) => {
  if (!p) return ''
  if (typeof p === 'string') return clean(p)
  if (typeof p === 'object') return clean(p.description ?? p.style ?? p.text ?? Object.values(p).filter((v) => typeof v === 'string').join(', '))
  return ''
}

try {
  const scene = $(SCENE_NODE).first().json
  if (!scene?.scene_id) throw new Error(`Нет шота в узле «${SCENE_NODE}»`)
  const topic = $(TOPIC_NODE).first().json
  const season = $(SEASON_NODE).first().json ?? {}

  const text = clean(scene.dialogue_text)
  if (!text) throw new Error('У шота нет текста (dialogue_text) — озвучивать нечего')
  const speaker = clean(scene.speaking_character)
  if (!speaker) throw new Error('У шота не указан говорящий (speaking_character)')
  if (scene.shot_type === 'talk' && norm(speaker) !== NARRATOR)
    throw new Error('#talk-шот: реплику говорит видео (H3, голос и губы) — отдельная озвучка не нужна')

  const byName = new Map()
  try {
    for (const { json: c } of $(CHARACTERS_NODE).all()) if (c?.name) byName.set(norm(c.name), c)
  } catch {
    /* узла нет — голос только из шота */
  }
  const character = byName.get(norm(speaker))
  const voice = clean(scene.speaking_character_voice) || clean(character?.voice_name)
  if (!voice)
    throw new Error(`Нет голоса у «${speaker}»: впишите voice_name персонажу (Персонажи → карточка) или speaking_character_voice шоту`)

  const tone = clean(scene.dialogue_direction || scene.speaker_voice_tone)
  const profile = profileText(character?.voice_profile) || (norm(speaker) === NARRATOR ? NARRATOR_VOICE : '')
  // «Old fierce warrior-sage, deep rough voice. Say in a grave tone»
  const style = [profile.replace(/[.\s]+$/, ''), tone ? `Say in a ${tone} tone` : 'Say'].filter(Boolean).join('. ')

  const output_dir = `anima/${season.folder || topic.season_id}/${topic.folder || topic.topic_id}`
  const file_name = `${String(scene.scena ?? 0).padStart(2, '0')}-${scene.shot_num ?? 1}.wav`

  return [{ json: { scene_id: scene.scene_id, text, voice, style, tts_url: TTS_URL, local_comfy_url: LOCAL_COMFY_URL, output_dir, file_name } }]
} catch (error) {
  return [{ json: { error: error.message } }]
}

// ═══════════════════════════════════════════════════════════════════════════
// audio_result.js — n8n Code-узел «Wav info» конвейера озвучки (n8n на .99). Mode: Run Once for All Items.
//
// Вход: binary.data — wav от tts-proxy (узел «TTS», Response Format: File).
// Считает длительность по заголовку WAV и даёт файлу имя <NN>-<шот>.wav (Vars.file_name),
// чтобы локальный ComfyUI сохранил его так (при повторе — «<NN>-<шот> (1).wav», старые остаются).
// Выход: json.audio_duration (сек), binary.data — тот же wav с нужным именем.
// ═══════════════════════════════════════════════════════════════════════════

const VARS_NODE = 'Vars'

const item = $input.first()
const bin = item.binary?.data
if (!bin) throw new Error('tts-proxy не вернул файл (нет binary.data) — проверьте узел TTS: Response Format = File')
const buf = await this.helpers.getBinaryDataBuffer(0, 'data')
if (buf.toString('ascii', 0, 4) !== 'RIFF' || buf.toString('ascii', 8, 12) !== 'WAVE') throw new Error(`Ответ tts-proxy — не wav: ${buf.toString('utf8', 0, 200)}`)

// Ищем чанки fmt и data (заголовок не обязательно 44 байта)
let rate = 24000
let blockAlign = 2
let dataSize = buf.length - 44
for (let p = 12; p + 8 <= buf.length; ) {
  const id = buf.toString('ascii', p, p + 4)
  const size = buf.readUInt32LE(p + 4)
  if (id === 'fmt ') {
    rate = buf.readUInt32LE(p + 12)
    blockAlign = buf.readUInt16LE(p + 20)
  }
  if (id === 'data') {
    dataSize = Math.min(size, buf.length - p - 8)
    break
  }
  p += 8 + size + (size % 2)
}
const audio_duration = Math.round((dataSize / (rate * blockAlign)) * 100) / 100

const file_name = $(VARS_NODE).first().json.file_name
return [{ json: { audio_duration }, binary: { data: { ...bin, fileName: file_name, mimeType: 'audio/wav', fileExtension: 'wav' } } }]
